// Forward-run statistics, exactly as pre-registered (docs/DESIGN.md "Forward run").

const MIN_CLAIM_N = 24;
const EXACT_MAX_N = 20;

/** Two-sided exact McNemar p-value over discordant counts b and c. */
export function mcnemarExact(b: number, c: number): number {
  const n = b + c;
  if (n === 0) return 1;
  const k = Math.min(b, c);
  // P(X <= k) for X ~ Binomial(n, 0.5), in log space to stay stable for large n.
  let logC = 0; // log C(n, 0)
  let tail = 0;
  for (let i = 0; i <= k; i++) {
    if (i > 0) logC += Math.log(n - i + 1) - Math.log(i);
    tail += Math.exp(logC - n * Math.LN2);
  }
  return Math.min(1, 2 * tail);
}

function normalCdf(z: number): number {
  // Abramowitz-Stegun 7.1.26 erf approximation.
  const x = Math.abs(z) / Math.SQRT2;
  const t = 1 / (1 + 0.3275911 * x);
  const poly =
    t * (0.254829592 + t * (-0.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429))));
  const erf = 1 - poly * Math.exp(-x * x);
  return z >= 0 ? 0.5 * (1 + erf) : 0.5 * (1 - erf);
}

/**
 * Wilcoxon signed-rank test. Zeros are dropped, ties get average ranks.
 * w is the smaller of the positive and negative rank sums. Exact for n <= 20,
 * normal approximation (tie- and continuity-corrected) above.
 */
export function wilcoxonSignedRank(diffs: number[]): { w: number; p: number; n: number } {
  const nz = diffs.filter((d) => d !== 0 && Number.isFinite(d));
  const n = nz.length;
  if (n < 1) return { w: 0, p: 1, n: 0 };

  const sorted = nz.map((d) => ({ abs: Math.abs(d), pos: d > 0 })).sort((a, b) => a.abs - b.abs);
  const ranks = new Array<number>(n);
  const tieSizes: number[] = [];
  for (let i = 0; i < n; ) {
    let j = i;
    while (j + 1 < n && sorted[j + 1].abs === sorted[i].abs) j++;
    const avg = (i + j) / 2 + 1;
    for (let k = i; k <= j; k++) ranks[k] = avg;
    tieSizes.push(j - i + 1);
    i = j + 1;
  }
  let wPos = 0;
  let wNeg = 0;
  sorted.forEach((s, i) => {
    if (s.pos) wPos += ranks[i];
    else wNeg += ranks[i];
  });
  const w = Math.min(wPos, wNeg);

  if (n <= EXACT_MAX_N) {
    // Average ranks are multiples of 0.5: double them so rank sums are integers.
    const r2 = ranks.map((r) => Math.round(r * 2));
    const total = r2.reduce((a, b) => a + b, 0);
    const dist = new Array<number>(total + 1).fill(0);
    dist[0] = 1;
    for (const r of r2) for (let s = total; s >= r; s--) dist[s] += dist[s - r];
    const w2 = Math.round(w * 2);
    let tail = 0;
    for (let s = 0; s <= w2; s++) tail += dist[s];
    return { w, p: Math.min(1, (2 * tail) / 2 ** n), n };
  }

  const mean = (n * (n + 1)) / 4;
  const tieCorr = tieSizes.reduce((a, t) => a + (t ** 3 - t), 0) / 48;
  const variance = (n * (n + 1) * (2 * n + 1)) / 24 - tieCorr;
  if (variance <= 0) return { w, p: 1, n };
  const z = (Math.abs(w - mean) - 0.5) / Math.sqrt(variance);
  return { w, p: Math.min(1, 2 * (1 - normalCdf(Math.max(z, 0)))), n };
